def test_upgrade_v1_to_v2():
    # Basic v1 -> v2
    r1 = {"id": 1, "name": "test", "remote": "yes"}
    r2 = upgrade(r1)
    assert r2 == {"id": 1, "title": "test", "work_mode": "remote", "version": 2}
    assert r1 != r2
    assert r1 == {"id": 1, "name": "test", "remote": "yes"}

    # remote: no -> office
    r3 = {"id": 2, "name": "test2", "remote": "no"}
    r4 = upgrade(r3)
    assert r4 == {"id": 2, "title": "test2", "work_mode": "office", "version": 2}

    # remote missing -> unknown
    r5 = {"id": 3, "name": "test3"}
    r6 = upgrade(r5)
    assert r6 == {"id": 3, "title": "test3", "work_mode": "unknown", "version": 2}

    # remote other -> ValueError
    try:
        upgrade({"id": 4, "name": "test4", "remote": "maybe"})
    except ValueError:
        pass
    else:
        assert False, "Should have raised ValueError for 'maybe'"

def test_upgrade_v2_idempotent():
    r1 = {"version": 2, "id": 1, "title": "test", "work_mode": "remote"}
    r2 = upgrade(r1)
    assert r2 == r1
    assert r1 is not r2

def test_load_all():
    rows = [
        {"id": 1, "name": "v1", "remote": "yes"},
        {"version": 2, "id": 2, "title": "v2", "work_mode": "office"}
    ]
    result = load_all(rows)
    assert len(result) == 2
    assert result[0] == {"id": 1, "title": "v1", "work_mode": "remote", "version": 2}
    assert result[1] == {"version": 2, "id": 2, "title": "v2", "work_mode": "office"}

