    # save v1
    r1 = {"id": 1, "name": "v1", "remote": "yes"}
    r2 = save(r1)
    assert r2 == {"id": 1, "title": "v1", "work_mode": "remote", "version": 2}

    # save v2
    r3 = {"version": 2, "id": 2, "title": "v2", "work_mode": "office"}
    r4 = save(r3)
    assert r4 == r3
    assert r3 is not r4

if __name__ == "__main__":
